package ly.com.tahaben.privileged_access_domain

/** Why the phone no longer lets Farhan in. The UI sends the user to pairing (or to Developer options). */
enum class LinkLostReason { NOT_PAIRED, KEY_REJECTED, WIRELESS_DEBUGGING_OFF }

sealed interface AccessFailure {
    /** The retained link is gone or unusable: pair again, or switch wireless debugging back on. */
    data class LinkLost(val reason: LinkLostReason) : AccessFailure

    /** Shizuku is installed but its service is not running: start it from the Shizuku app. */
    data object ShizukuNotRunning : AccessFailure

    /** Any other reason the route could not run the command. [blocker] says which. */
    data class RouteBlocked(val route: Route, val blocker: RouteBlocker) : AccessFailure

    /** The shell ran the command and it failed. [output] is cleaned text from the shell. */
    data class CommandFailed(val route: Route, val exitCode: Int, val output: String) : AccessFailure

    /** The command ran cleanly and the phone still disagrees. */
    data class NotEffective(val route: Route) : AccessFailure

    /** Another command is already running. */
    data object Busy : AccessFailure

    /** Farhan's own application id was not a valid package name, so no command was built. */
    data object InvalidAppId : AccessFailure
}

sealed interface AccessResult {
    /** [verified] is false when the phone could not be read back and the shell's clean exit was trusted. */
    data class Done(val command: PrivilegedCommand, val route: Route, val verified: Boolean) : AccessResult

    /** The preference is "ask" and there is no link: the caller picks a route and calls again. */
    data class ChooseRoute(val options: List<Route>) : AccessResult

    data class Failed(val failure: AccessFailure) : AccessResult
}

object OutputText {
    private const val MAX_CHARS = 1000

    /** Shell output for display: control characters other than newline removed, trimmed, at most 1000 characters. */
    fun clean(raw: String): String =
        raw.filter { it == '\n' || !it.isISOControl() }.trim().let { if (it.length > MAX_CHARS) it.take(MAX_CHARS) + "…" else it }
}

object AccessMapper {
    /** A shell result that did not run the command. */
    fun failureOf(route: Route, blocker: RouteBlocker): AccessFailure = when (blocker) {
        RouteBlocker.NOT_PAIRED -> AccessFailure.LinkLost(LinkLostReason.NOT_PAIRED)
        RouteBlocker.KEY_REJECTED -> AccessFailure.LinkLost(LinkLostReason.KEY_REJECTED)
        RouteBlocker.WIRELESS_DEBUGGING_OFF -> AccessFailure.LinkLost(LinkLostReason.WIRELESS_DEBUGGING_OFF)
        RouteBlocker.SHIZUKU_NOT_RUNNING -> AccessFailure.ShizukuNotRunning
        else -> AccessFailure.RouteBlocked(route, blocker)
    }

    /** A shell result that ran: a clean exit goes on to be checked against the phone, anything else is a failure. */
    fun commandFailure(route: Route, ran: ShellResult.Ran): AccessFailure =
        AccessFailure.CommandFailed(route, ran.exitCode, OutputText.clean(ran.output))
}
package ly.com.tahaben.privileged_access_domain

/** What Android says about an app-op, reduced to what the connector needs. */
enum class AppOpMode {
    ALLOWED, NOT_ALLOWED,
    /** The platform could not tell (unknown op name on this build). Granting is harmless, so it is treated as not allowed. */
    UNKNOWN;

    companion object {
        /** `AppOpsManager.MODE_ALLOWED` is 0; ignored, errored, default and foreground are all "not allowed" for a listener. */
        fun fromPlatformMode(mode: Int?): AppOpMode = when (mode) {
            null -> UNKNOWN
            0 -> ALLOWED
            else -> NOT_ALLOWED
        }
    }
}

/** Facts read from the phone, with no shell and no side effect. */
data class AccessFacts(
    val sdk: Int,
    val sensitiveNotificationsOp: AppOpMode,
    /** `PackageManager.checkPermission(WRITE_SECURE_SETTINGS)`. */
    val secureSettingsPermissionHeld: Boolean,
    /** Whether a write actually went through; null when it was not tried (it is tried only after a grant). */
    val secureSettingsWriteWorked: Boolean? = null,
)

enum class AccessState {
    ALLOWED,
    NOT_ALLOWED,
    /** The phone has nothing to grant (the app-op exists from Android 15). */
    NOT_APPLICABLE,
}

/** What the UI shows: where the link stands and, per access, whether it is allowed. All of it comes from [AccessFacts] and [RouteReadiness]. */
data class PrivilegedStatus(
    val checked: Boolean,
    val link: LinkState,
    val accesses: Map<Access, AccessState>,
    val routes: Map<Route, RouteReadiness>,
) {
    fun stateOf(access: Access): AccessState? = accesses[access]

    /** Not allowed and no route can run the grant: the user has to pair or start Shizuku first. */
    fun needsSetup(access: Access): Boolean = accesses[access] == AccessState.NOT_ALLOWED && link == LinkState.None &&
        routes.values.none { it is RouteReadiness.Ready || (it as? RouteReadiness.Blocked)?.blocker?.askInApp == true }

    /** True when the allowed accesses can be revoked without a new pairing. */
    val canRevoke: Boolean get() = link != LinkState.None

    companion object {
        val UNCHECKED = PrivilegedStatus(checked = false, link = LinkState.None, accesses = emptyMap(), routes = emptyMap())
    }
}

object AccessDecider {
    /** First Android with RECEIVE_SENSITIVE_NOTIFICATIONS. */
    const val SENSITIVE_NOTIFICATIONS_SINCE_SDK = 35

    fun decide(access: Access, facts: AccessFacts): AccessState = when (access) {
        Access.SENSITIVE_NOTIFICATIONS -> when {
            facts.sdk < SENSITIVE_NOTIFICATIONS_SINCE_SDK -> AccessState.NOT_APPLICABLE
            facts.sensitiveNotificationsOp == AppOpMode.ALLOWED -> AccessState.ALLOWED
            else -> AccessState.NOT_ALLOWED
        }
        // The permission is what Android checks for every write, so holding it is enough unless a write was tried and failed.
        Access.SECURE_SETTINGS ->
            if (facts.secureSettingsPermissionHeld && facts.secureSettingsWriteWorked != false) AccessState.ALLOWED else AccessState.NOT_ALLOWED
    }

    fun decideAll(facts: AccessFacts): Map<Access, AccessState> = Access.entries.associateWith { decide(it, facts) }

    /**
     * The link is the route that could run a command now. Under a fixed [RoutePreference] only that route counts;
     * under ASK, Self-ADB is looked at first because it needs no other app.
     */
    fun linkOf(preference: RoutePreference, readiness: Map<Route, RouteReadiness>): LinkState {
        val candidates = when (preference) {
            RoutePreference.ASK -> listOf(Route.SELF_ADB, Route.SHIZUKU)
            RoutePreference.SELF_ADB -> listOf(Route.SELF_ADB)
            RoutePreference.SHIZUKU -> listOf(Route.SHIZUKU)
        }
        val ready = candidates.firstOrNull { readiness[it] == RouteReadiness.Ready } ?: return LinkState.None
        return LinkState.Connected(ready)
    }

    fun statusOf(facts: AccessFacts, preference: RoutePreference, readiness: Map<Route, RouteReadiness>) = PrivilegedStatus(
        checked = true,
        link = linkOf(preference, readiness),
        accesses = decideAll(facts),
        routes = readiness,
    )

    /** True when neither access is allowed, so a retained key has no further use. */
    fun nothingAllowed(accesses: Map<Access, AccessState>): Boolean =
        accesses.isNotEmpty() && accesses.values.none { it == AccessState.ALLOWED }
}
package ly.com.tahaben.privileged_access_domain

/** The route the user prefers. [ASK] is the default: Farhan never picks a way into the phone the user did not choose. */
enum class RoutePreference {
    ASK, SELF_ADB, SHIZUKU;

    companion object {
        val DEFAULT = ASK

        /** An unknown stored value (an old or edited backup) falls back to [DEFAULT]. */
        fun fromStored(stored: String?): RoutePreference = entries.firstOrNull { it.name == stored } ?: DEFAULT
    }
}

sealed interface RouteChoice {
    data class Use(val route: Route) : RouteChoice
    data class AskUser(val options: List<Route>) : RouteChoice
}

object RouteChooser {
    /**
     * In order: the route the caller named for this one command; the stored preference when it names a route; the
     * route of the retained link (a second access runs over the first one's link with no pairing flow); otherwise
     * ask.
     */
    fun choose(requested: Route?, preference: RoutePreference, link: LinkState): RouteChoice = when {
        requested != null -> RouteChoice.Use(requested)
        preference == RoutePreference.SELF_ADB -> RouteChoice.Use(Route.SELF_ADB)
        preference == RoutePreference.SHIZUKU -> RouteChoice.Use(Route.SHIZUKU)
        link is LinkState.Connected -> RouteChoice.Use(link.route)
        else -> RouteChoice.AskUser(Route.entries)
    }
}
package ly.com.tahaben.privileged_access_domain

/** The two ways to reach a shell that can run a [PrivilegedCommand]. */
enum class Route { SELF_ADB, SHIZUKU }

/** Why a route cannot run a command right now. Each one is something the user can read and act on. */
enum class RouteBlocker {
    /** Self-ADB needs wireless debugging, which starts at Android 11. */
    ANDROID_TOO_OLD,
    /** No retained adb key: Farhan has not been paired, or the pairing was forgotten. */
    NOT_PAIRED,
    /** The phone refused Farhan's key: the pairing was removed in Developer options. The retained key is dead. */
    KEY_REJECTED,
    /** Wireless debugging is off, or its daemon could not be found. The retained key may still be good. */
    WIRELESS_DEBUGGING_OFF,
    /** The daemon answered but the connection broke or timed out. Worth trying again. */
    CONNECTION_FAILED,
    SHIZUKU_NOT_INSTALLED,
    SHIZUKU_NOT_RUNNING,
    SHIZUKU_TOO_OLD,
    /** Shizuku is running and Farhan has not asked yet. One in-app prompt fixes it. */
    SHIZUKU_PERMISSION_NEEDED,
    SHIZUKU_PERMISSION_DENIED,
    /** Shizuku granted the permission but its service did not start in time. */
    SHIZUKU_SERVICE_FAILED;

    /** True when the user can fix it without leaving Farhan's own screens. */
    val askInApp: Boolean get() = this == SHIZUKU_PERMISSION_NEEDED
}

sealed interface RouteReadiness {
    data object Ready : RouteReadiness
    data class Blocked(val blocker: RouteBlocker) : RouteReadiness
}

sealed interface ShellResult {
    /** The command ran. [output] is its output; it is shown to the user on failure, so it is cleaned by [OutputText]. */
    data class Ran(val exitCode: Int, val output: String) : ShellResult

    /** The command did not run. Nothing changed on the phone. */
    data class Blocked(val blocker: RouteBlocker) : ShellResult
}

/**
 * A back end that runs one [ShellCommand] with shell rights. It cannot run anything else: the type has no way to
 * carry free text.
 */
interface PrivilegedShell {
    val route: Route

    /** Looks at stored state and system settings only. It opens no connection and runs nothing. */
    suspend fun readiness(): RouteReadiness

    suspend fun run(command: ShellCommand): ShellResult
}

/** A one-time pairing code. [toString] hides it, and nothing in the connector stores it. */
@JvmInline
value class PairingCode private constructor(private val digits: String) {
    fun reveal(): String = digits
    override fun toString() = "PairingCode(******)"

    companion object {
        private val SHAPE = Regex("[0-9]{6}")
        fun parse(raw: String): PairingCode? = raw.trim().takeIf { SHAPE.matches(it) }?.let(::PairingCode)
    }
}

sealed interface PairingResult {
    data object Paired : PairingResult
    data object AndroidTooOld : PairingResult
    /** The pairing service was not found: the user has not opened "Pair device with pairing code". */
    data object PairingServiceNotFound : PairingResult
    /** Wrong or expired code, or the dialog was closed. */
    data object Rejected : PairingResult
    data object Failed : PairingResult
}

sealed interface ShizukuPermissionResult {
    data object Granted : ShizukuPermissionResult
    data class Blocked(val blocker: RouteBlocker) : ShizukuPermissionResult
}

/** Self-ADB: the phone's own wireless-debugging daemon, reached over loopback with a key Farhan keeps. */
interface SelfAdbRoute : PrivilegedShell {
    /**
     * Pairs once. [pairingPort] null means find it through service discovery. On success the key is retained and the
     * code is gone: it is never stored.
     */
    suspend fun pair(code: PairingCode, pairingPort: Int?): PairingResult

    /** Deletes the retained key. The phone's paired-devices entry stays until the user removes it. */
    fun forgetPairing()
}

/** Shizuku: its running service hands out a shell process after the user allows Farhan in Shizuku. */
interface ShizukuRoute : PrivilegedShell {
    suspend fun requestPermission(): ShizukuPermissionResult
}

/** Where the link stands. [Connected] means a route could run a command now, without any pairing flow. */
sealed interface LinkState {
    data object None : LinkState
    data class Connected(val route: Route) : LinkState
}
package ly.com.tahaben.privileged_access_domain

/** The two things Farhan asks the phone to allow. Neither can be granted by tapping a normal permission prompt. */
enum class Access {
    /** Android 15 and later hide a one-time code's text from listeners without this app-op. */
    SENSITIVE_NOTIFICATIONS,

    /** Lets the Grayscale feature write the secure settings that tint the screen. */
    SECURE_SETTINGS,
}

/**
 * The application id a command is for. Only a well-formed id exists as a value, so no other text ever reaches a
 * command line. Production passes `context.packageName`.
 */
@JvmInline
value class AppId private constructor(val value: String) {
    companion object {
        private val SHAPE = Regex("[A-Za-z][A-Za-z0-9_]*(\\.[A-Za-z][A-Za-z0-9_]*)+")

        fun parse(raw: String): AppId? = raw.takeIf { it.length <= 255 && SHAPE.matches(it) }?.let(::AppId)
    }
}

/**
 * One command line as separate words. The only way to make one is [PrivilegedCommand.shellCommand], and every word
 * must be letters, digits, `.` or `_`: nothing a shell treats specially, so no quoting is needed and no untrusted
 * text can add a second command. A shell back end may join [args] with spaces; a process back end passes them as an
 * argument vector.
 */
class ShellCommand private constructor(val args: List<String>) {
    val line: String get() = args.joinToString(" ")

    override fun equals(other: Any?) = other is ShellCommand && other.args == args
    override fun hashCode() = args.hashCode()
    override fun toString() = line

    companion object {
        private val WORD = Regex("[A-Za-z0-9._]{1,255}")

        /** The two programs the connector ever runs. A process that executes commands checks against this. */
        val PROGRAMS: Set<String> = setOf("appops", "pm")

        /** True when [args] could have come from [PrivilegedCommand.shellCommand]: a known program, safe words only. */
        fun isAllowed(args: List<String>): Boolean =
            args.size in 3..8 && args.first() in PROGRAMS && args.all { WORD.matches(it) }

        internal fun of(args: List<String>): ShellCommand {
            require(isAllowed(args)) { "not a connector command" }
            return ShellCommand(args)
        }
    }
}

/**
 * Every command the connector can run, as a closed list. Revoking is a command too and runs over the same link.
 *
 * `appops set ... default` is used to revoke the app-op, not `appops reset <package>`: reset would also wipe every
 * other app-op Farhan holds (usage access, for one).
 */
enum class PrivilegedCommand(val access: Access, val grants: Boolean) {
    GRANT_SENSITIVE_NOTIFICATIONS(Access.SENSITIVE_NOTIFICATIONS, grants = true),
    REVOKE_SENSITIVE_NOTIFICATIONS(Access.SENSITIVE_NOTIFICATIONS, grants = false),
    GRANT_SECURE_SETTINGS(Access.SECURE_SETTINGS, grants = true),
    REVOKE_SECURE_SETTINGS(Access.SECURE_SETTINGS, grants = false);

    fun shellCommand(app: AppId): ShellCommand = ShellCommand.of(
        when (this) {
            GRANT_SENSITIVE_NOTIFICATIONS -> listOf("appops", "set", app.value, APP_OP_SENSITIVE_NOTIFICATIONS, "allow")
            REVOKE_SENSITIVE_NOTIFICATIONS -> listOf("appops", "set", app.value, APP_OP_SENSITIVE_NOTIFICATIONS, "default")
            GRANT_SECURE_SETTINGS -> listOf("pm", "grant", app.value, PERMISSION_WRITE_SECURE_SETTINGS)
            REVOKE_SECURE_SETTINGS -> listOf("pm", "revoke", app.value, PERMISSION_WRITE_SECURE_SETTINGS)
        },
    )

    companion object {
        const val APP_OP_SENSITIVE_NOTIFICATIONS = "RECEIVE_SENSITIVE_NOTIFICATIONS"
        const val PERMISSION_WRITE_SECURE_SETTINGS = "android.permission.WRITE_SECURE_SETTINGS"

        fun of(access: Access, grants: Boolean): PrivilegedCommand = entries.first { it.access == access && it.grants == grants }
    }
}

