/**
 * The layer the UI calls. Rules it keeps:
 *  - It runs a command only inside [grant] or [revoke], which the user starts. [refresh] reads the phone and stored
 *    state and opens no connection.
 *  - Every command is one of [PrivilegedCommand]; nothing here takes free text.
 *  - The link outlives a grant: a second access runs over the same retained key (or Shizuku permission), with no
 *    pairing flow. A pairing code is used once and never kept.
 */
interface PrivilegedAccess {
    /** Link and per-access state. Starts as [PrivilegedStatus.UNCHECKED] until the first [refresh]. */
    val status: StateFlow<PrivilegedStatus>
    val routePreference: StateFlow<RoutePreference>

    /** Re-reads everything. Call when the app returns to the foreground. */
    suspend fun refresh(): PrivilegedStatus

    suspend fun grant(access: Access, route: Route? = null): AccessResult
    suspend fun revoke(access: Access, route: Route? = null): AccessResult

    suspend fun pairSelfAdb(code: PairingCode, pairingPort: Int?): PairingResult
    suspend fun requestShizukuPermission(): ShizukuPermissionResult

    suspend fun setRoutePreference(preference: RoutePreference)

    /** The user asked to forget the retained adb key. */
    suspend fun forgetSelfAdbKey()
}

class DefaultPrivilegedAccess(
    appId: String,
    private val phone: PhoneFacts,
    private val selfAdb: SelfAdbRoute,
    private val shizuku: ShizukuRoute,
    private val preferences: PrivilegedPreferences,
    private val rebinder: ListenerRebinder,
    private val redaction: OtpRedactionFlag,
    private val grayscale: GrayscaleReset,
    private val io: CoroutineDispatcher = Dispatchers.IO,
) : PrivilegedAccess {
    private val app: AppId? = AppId.parse(appId)
    private val statusFlow = MutableStateFlow(PrivilegedStatus.UNCHECKED)
    private val preferenceFlow = MutableStateFlow(preferences.route)
    private val busy = Mutex()

    /** Self-ADB looked usable on paper but the daemon was not there. In memory: a restart starts clean. */
    private val lostRoutes = ConcurrentHashMap<Route, RouteBlocker>()
    @Volatile private var lastSelfAdbReadiness: RouteReadiness? = null

    override val status: StateFlow<PrivilegedStatus> = statusFlow.asStateFlow()
    override val routePreference: StateFlow<RoutePreference> = preferenceFlow.asStateFlow()

    override suspend fun refresh(): PrivilegedStatus = withContext(io) { publish(settlePending = !busy.isLocked) }

    override suspend fun grant(access: Access, route: Route?) = execute(PrivilegedCommand.of(access, grants = true), route)

    override suspend fun revoke(access: Access, route: Route?) = execute(PrivilegedCommand.of(access, grants = false), route)

    override suspend fun pairSelfAdb(code: PairingCode, pairingPort: Int?): PairingResult = withContext(io) {
        if (pairingPort != null && pairingPort !in 1..65535) return@withContext PairingResult.Failed
        if (!busy.tryLock()) return@withContext PairingResult.Failed
        try {
            selfAdb.pair(code, pairingPort).also { result ->
                if (result == PairingResult.Paired) lostRoutes.remove(Route.SELF_ADB)
                publish(settlePending = false)
            }
        } finally {
            busy.unlock()
        }
    }

    override suspend fun requestShizukuPermission(): ShizukuPermissionResult =
        shizuku.requestPermission().also { withContext(io) { publish(settlePending = !busy.isLocked) } }

    override suspend fun setRoutePreference(preference: RoutePreference) {
        withContext(io) {
            preferences.route = preference
            preferenceFlow.value = preference
            publish(settlePending = !busy.isLocked)
        }
    }

    override suspend fun forgetSelfAdbKey() {
        withContext(io) {
            selfAdb.forgetPairing()
            lostRoutes.remove(Route.SELF_ADB)
            publish(settlePending = !busy.isLocked)
        }
    }

    private suspend fun execute(command: PrivilegedCommand, requested: Route?): AccessResult = withContext(io) {
        val appId = app ?: return@withContext AccessResult.Failed(AccessFailure.InvalidAppId)
        if (!busy.tryLock()) return@withContext AccessResult.Failed(AccessFailure.Busy)
        try {
            val before = publish(settlePending = false)
            val route = when (val choice = RouteChooser.choose(requested, preferenceFlow.value, before.link)) {
                is RouteChoice.AskUser -> return@withContext AccessResult.ChooseRoute(choice.options)
                is RouteChoice.Use -> choice.route
            }
            val otherAllowed = before.accesses.any { (access, state) -> access != command.access && state == AccessState.ALLOWED }
            if (!command.grants) {
                if (command.access == Access.SECURE_SETTINGS) grayscale.resetBeforeRevoke()
                if (!otherAllowed) preferences.linkDropPending = true
            }
            val shell = if (route == Route.SELF_ADB) selfAdb else shizuku
            val result = when (val ran = shell.run(command.shellCommand(appId))) {
                is ShellResult.Blocked -> {
                    onBlocked(route, ran.blocker)
                    AccessResult.Failed(AccessMapper.failureOf(route, ran.blocker))
                }
                is ShellResult.Ran -> {
                    lostRoutes.remove(route)
                    if (ran.exitCode != 0) AccessResult.Failed(AccessMapper.commandFailure(route, ran)) else verified(command, route)
                }
            }
            if (result is AccessResult.Done && command.grants && command.access == Access.SENSITIVE_NOTIFICATIONS) {
                rebinder.rebind()
                redaction.clear()
            }
            publish(settlePending = true)
            result
        } finally {
            busy.unlock()
        }
    }

    private fun onBlocked(route: Route, blocker: RouteBlocker) {
        when {
            // The phone removed our key: it is useless, so the link is cleared and the next grant needs pairing.
            blocker == RouteBlocker.KEY_REJECTED -> selfAdb.forgetPairing()
            route == Route.SELF_ADB && blocker == RouteBlocker.WIRELESS_DEBUGGING_OFF -> lostRoutes[route] = blocker
        }
    }

    /** Compares the phone with what the command should have done. A clean exit with no change is [AccessFailure.NotEffective]. */
    private fun verified(command: PrivilegedCommand, route: Route): AccessResult {
        val done = { verified: Boolean -> AccessResult.Done(command, route, verified) }
        val notEffective = AccessResult.Failed(AccessFailure.NotEffective(route))
        return when (command) {
            PrivilegedCommand.GRANT_SENSITIVE_NOTIFICATIONS -> when (phone.sensitiveNotificationsOp()) {
                AppOpMode.ALLOWED -> done(true)
                AppOpMode.UNKNOWN -> done(false)
                AppOpMode.NOT_ALLOWED -> notEffective
            }
            PrivilegedCommand.REVOKE_SENSITIVE_NOTIFICATIONS -> when (phone.sensitiveNotificationsOp()) {
                AppOpMode.ALLOWED -> notEffective
                AppOpMode.NOT_ALLOWED -> done(true)
                AppOpMode.UNKNOWN -> done(false)
            }
            PrivilegedCommand.GRANT_SECURE_SETTINGS ->
                if (!phone.secureSettingsPermissionHeld() || phone.secureSettingsWriteWorks() == false) notEffective else done(true)
            PrivilegedCommand.REVOKE_SECURE_SETTINGS ->
                if (phone.secureSettingsPermissionHeld()) notEffective else done(true)
        }
    }

    private suspend fun readReadiness(): Map<Route, RouteReadiness> {
        val own = selfAdb.readiness()
        // Wireless debugging switched back on clears the "daemon not found" mark; otherwise it stays until an attempt reaches the daemon or the user pairs again.
        if (own == RouteReadiness.Ready && lastSelfAdbReadiness == RouteReadiness.Blocked(RouteBlocker.WIRELESS_DEBUGGING_OFF)) lostRoutes.remove(Route.SELF_ADB)
        lastSelfAdbReadiness = own
        val selfAdbReadiness = if (own == RouteReadiness.Ready) lostRoutes[Route.SELF_ADB]?.let { RouteReadiness.Blocked(it) } ?: own else own
        return mapOf(Route.SELF_ADB to selfAdbReadiness, Route.SHIZUKU to shizuku.readiness())
    }

    /**
     * Reads the phone, finishes an interrupted revoke when [settlePending], and publishes the result. A revoke that
     * left nothing allowed drops the retained adb key; one that did not take just clears the marker.
     */
    private suspend fun publish(settlePending: Boolean): PrivilegedStatus {
        var status = compute()
        if (settlePending && preferences.linkDropPending) {
            if (AccessDecider.nothingAllowed(status.accesses)) {
                selfAdb.forgetPairing()
                lostRoutes.remove(Route.SELF_ADB)
            }
            preferences.linkDropPending = false
            status = compute()
        }
        statusFlow.value = status
        return status
    }

    private suspend fun compute(): PrivilegedStatus {
        val facts = AccessFacts(
            sdk = phone.sdk,
            sensitiveNotificationsOp = phone.sensitiveNotificationsOp(),
            secureSettingsPermissionHeld = phone.secureSettingsPermissionHeld(),
        )
        return AccessDecider.statusOf(facts, preferenceFlow.value, readReadiness())

function inbox(){
  const cleared = S.inboxTab === 'cleared';
  const list = S.notes.filter(n => n.cleared === cleared);
  const sel = list.filter(n => S.selected.has(n.id)).length;
  const label = cleared ? 'Empty' : (sel ? `Clear ${sel}` : 'Clear');
  let body = '';
  if (!list.length) body = `<div class="empty">${cleared ? 'Nothing cleared yet.' : 'Nothing here. New notifications appear as they arrive.'}</div>`;
  else if (cleared) body = list.map(row).join('');
  else {
    const codes = S.codes.raise ? list.filter(n => n.code) : [];
    const rest = list.filter(n => !codes.includes(n));
    if (codes.length) body += `<div class="sec">Codes</div>` + codes.map(row).join('');
    for (const [k, h] of [['waiting','Waiting to send'],['unsent','Not sent'],['sent','Sent']]) {
      const g = rest.filter(n => n.d === k);
      if (g.length) body += `<div class="sec">${h}<small>${g.length}</small></div>` + g.map(row).join('');
    }
  }
  return `<div class="hdr"><div class="tabs"><button class="${cleared?'':'on'}" data-itab="inbox">Inbox</button><button class="${cleared?'on':''}" data-itab="cleared">Cleared</button></div><button class="act" data-clear ${list.length?'':'disabled'}>${label}</button></div><div class="scroll">${body}</div>`;
}
function summary(){
  const live = S.notes.filter(n => !n.cleared), v = S.variant;
  const c = k => live.filter(n => n.d === k).length;
  const waiting = c('waiting'), sent = c('sent'), unsent = c('unsent');
  const bars = [2,1,0,0,0,1,3,5,4,3,2,2,3,4,3,2,3,5,6,4,3,2,1,1].map(h => `<b style="height:${h*14}%"></b>`).join('');
  let b = '';
  if (v === 'a') {
    b += `<div class="card"><h4>Notifications today</h4><div class="kv"><span>Waiting to send</span><span>${waiting}</span></div><div class="kv"><span>Sent</span><span>${sent}</span></div><div class="kv"><span>Not sent</span><span>${unsent}</span></div><div class="kv"><span>Next delivery</span><span>8:30 PM</span></div></div>`;
    if (S.feat.usage) b += `<div class="card"><h4>Screen time</h4><div class="big">3h 12m</div><div class="bar" style="margin:8px 0"><b style="width:64%"></b></div><div class="kv"><span>Goal</span><span>5h</span></div></div>`;
    if (S.feat.focus) b += `<div class="card"><h4>Focus tools</h4><div class="kv"><span>Scrolls blocked</span><span>14</span></div><div class="kv"><span>Mindful launches</span><span>6</span></div></div>`;
  } else if (v === 'b') {
    b += `<div class="card"><h4>Today by hour</h4><div class="tl">${bars}</div><div class="kv"><span>12 AM</span><span>12 PM</span><span>11 PM</span></div></div>`;
    b += `<div class="card"><h4>Needs you</h4><div class="kv"><span>${waiting} waiting to send</span><span>›</span></div><div class="kv"><span>${unsent} not sent</span><span>›</span></div></div>`;
    if (S.feat.usage) b += `<div class="card"><h4>Most used</h4><div class="kv"><span>Maya Chat</span><span>58m</span></div><div class="kv"><span>News</span><span>41m</span></div></div>`;
  } else {
    b += `<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><div class="card"><div class="big">${live.length}</div><div class="kv"><span>in Inbox</span></div></div><div class="card"><div class="big">${sent}</div><div class="kv"><span>sent</span></div></div>`;
    if (S.feat.usage) b += `<div class="card"><div class="big">3h</div><div class="kv"><span>screen time</span></div></div>`;
    if (S.feat.focus) b += `<div class="card"><div class="big">14</div><div class="kv"><span>blocked</span></div></div>`;
    b += `</div>`;
  }
  return `<div class="title">Summary</div><div class="scroll">${b}</div>`;
}
function simple(title, items, note){ return `<div class="title">${title}</div><div class="scroll"><div class="group">${items.map(i=>`<div class="row"><div class="mid">${i[0]}${i[1]?`<small>${i[1]}</small>`:''}</div><span>›</span></div>`).join('')}</div><div class="note">${note}</div></div>` }
function accessRow(title, why, state, flowName){
  const on = state === 'on';
  const right = !flowName ? '<span class="pill"><i class="a"></i>Allowed</span>' : (S.link || on) ? tog('a:'+flowName, on) : `<button class="btn" data-flow="${flowName}">Allow</button>`;
  return `<div class="row" style="cursor:default"><div class="mid">${title}<small>${why}</small></div>${right}</div>`;
}
function accessGroup(){
  return `<div class="group"><h4>Special access</h4>
    ${accessRow('Notification access','Reads notifications to hold and deliver them.','on')}
    ${accessRow('Accessibility','Lets the scroll blocker see scrolling.','on')}
    ${accessRow('Sensitive notifications','Lets Farhan read one-time codes on Android 15 and later.', S.access.sensitive?'on':'off','sensitive')}
    ${accessRow('Grayscale control','Lets Farhan switch the screen to grayscale.', S.access.secure?'on':'off','secure')}
    ${S.link?`<div class="row" style="cursor:default"><div class="mid">${S.link.route==='adb'?'Wireless debugging':'Shizuku'}<small>${S.link.route==='adb'?'Farhan keeps the key it paired with, not the code.':'Farhan keeps the Shizuku permission.'}</small></div><span class="pill"><i class="a"></i>Connected</span></div>`:''}
    <div class="note" style="margin-top:6px">${S.link?'Switch an access off to revoke it. Switch both off and Farhan forgets the pairing; the next Allow pairs again.':'Every access Farhan holds, and why. The first Allow pairs once; after that each access is a switch.'}</div></div>`;
}
function flowView(){
  const t = S.flow === 'sensitive' ? 'Allow sensitive notifications' : 'Allow grayscale control';
  const what = S.flow === 'sensitive' ? 'Android 15 and later hide a one-time code from apps like Farhan. This one-time step lets Farhan read it. Farhan then raises the code and offers Copy.' : 'This one-time step lets Farhan switch the screen to grayscale for you.';
  let body = `<button class="btn" data-fback style="align-self:flex-start">‹ Back</button><div class="card"><b>${t}</b><small style="display:block;color:var(--mute);margin-top:4px">${what}</small></div>`;
  if (S.result) {
    body += S.result.ok ? `<div class="card"><b>Allowed.</b><small style="display:block;color:var(--mute)">${S.flow==='sensitive'?'Codes now appear in the Inbox. Farhan rebound its notification access for you.':'Grayscale can now be switched on from Farhan.'} The other access is now a switch under Special access. Farhan keeps the key, not the code.</small></div><button class="btn pri" data-fback>Done</button>`
      : `<div class="warn">${S.result.msg}</div><button class="btn" data-retry>Try again</button>`;
    return body;
  }
  body += `<div class="sec">How do you want to allow it?</div>
    <div class="radio ${S.route==='adb'?'on':''}" data-route="adb"><span class="dot"></span><div><b>Wireless debugging on this phone</b><small style="display:block;color:var(--mute)">No computer needed. Farhan pairs with this phone once.</small></div></div>
    <div class="radio ${S.route==='shizuku'?'on':''}" data-route="shizuku"><span class="dot"></span><div><b>Shizuku</b><small style="display:block;color:var(--mute)">Use it if Shizuku is installed and running.</small></div></div>`;
  if (S.route === 'adb') {
    body += `<div class="card"><h4>Steps</h4>
      <div class="kv"><span>1</span><span style="flex:1;text-align:left;margin-left:10px">Turn on Developer options, then Wireless debugging.</span></div>
      <div class="kv"><span>2</span><span style="flex:1;text-align:left;margin-left:10px">Tap Pair device with pairing code.</span></div>
      <div class="kv"><span>3</span><span style="flex:1;text-align:left;margin-left:10px">Type the code and port below.</span></div>
      <div class="split"><div>Farhan</div><div>Settings</div></div>
      <small style="color:var(--mute)">Use split screen: Farhan on one half, Settings on the other. The pairing code disappears if you switch apps.</small></div>
      <button class="btn" data-toast="Opens Wireless debugging in system settings" style="align-self:flex-start">Open Wireless debugging</button>
      <input class="inp" placeholder="Pairing code (6 digits)" inputmode="numeric"><input class="inp" placeholder="Port">
      <button class="btn pri" data-go ${S.busy?'disabled':''}>${S.busy?'Allowing…':'Pair and allow'}</button>`;
  } else {
    body += `<div class="card"><small style="color:var(--mute)">Shizuku: <b style="color:var(--ink)">${S.outcome==='noshiz'?'not running':'running'}</b>. Farhan asks Shizuku for permission, then runs the command.</small></div>
      <button class="btn pri" data-go ${S.busy?'disabled':''}>${S.busy?'Allowing…':'Allow with Shizuku'}</button>`;
  }
  body += `<div class="note">Farhan runs one command, only when you tap the button. The code works once and is not stored. Farhan keeps only the key it pairs with.</div>`;
  return body;
}
function settings(){
  const T = [['features','Features'],['notifications','Notifications'],['apps','Apps'],['focus','Focus'],['more','More']];
  const tabs = `<div class="hdr"><div class="tabs">${T.map(t=>`<button class="${S.settingsTab===t[0]?'on':''}" data-stab="${t[0]}" style="padding:12px 2px;font-size:12px">${t[1]}</button>`).join('')}</div></div>`;
  let b = '';
  if (S.settingsTab === 'features') b = `<div class="group"><h4>Features</h4>${sw('Notification Inbox','Always on','',true,true)}${sw('Summary','Always on. One section per feature below.','',true,true)}${sw('Usage overview','Section in Summary','usage',S.feat.usage)}${sw('Launcher','Bottom tab','launcher',S.feat.launcher)}${sw('Focus tools','Bottom tab: scroll blocker, grayscale, time limit, mindful launch','focus',S.feat.focus)}</div><div class="note">Turning a feature off hides its tab or section and stops its service. Its saved settings are kept.</div>`;
  if (S.settingsTab === 'notifications') b = `<div class="group"><h4>Delivery</h4><div class="row"><div class="mid">Daily schedule<small>7:00 to 24:00, 12 per day</small></div><span>›</span></div><div class="row"><div class="mid">Notify me at<small>8:30 PM</small></div><span>›</span></div></div><div class="group"><h4>Verification codes</h4>${S.redaction&&!S.access.sensitive?`<div class="warn">Android is hiding codes from Farhan. <button class="btn" ${S.link?'data-tog="a:sensitive"':'data-flow="sensitive"'} style="margin-left:6px">Allow</button></div>`:''}${sw('Raise codes','Top of the Inbox, and as their own notification with Copy','raise',S.codes.raise)}<div class="row" data-scope><div class="mid">Only from<small>${S.codes.scope} · fresh for 10 minutes</small></div><span>›</span></div></div><div class="group"><h4>Sound</h4><div class="row"><div class="mid">Sound control<small>Quiet hours and per-priority sound</small></div><span>›</span></div></div><div class="group"><h4>Automation and labs</h4>${sw('Snooze (pilot)','','snooze',false)}</div>`;
  if (S.settingsTab === 'apps') {
    if (S.app !== null) { const a = S.apps[S.app];
      b = `<button class="btn" data-back style="align-self:flex-start">‹ Apps</button><div class="card" style="display:flex;gap:10px;align-items:center"><div class="ic">${a.name[0]}</div><b>${a.name}</b></div><div class="group"><h4>Notifications</h4><div class="row" data-cycle="prio"><div class="mid">Priority<small>${a.prio}</small></div><span>›</span></div><div class="row" data-cycle="sound"><div class="mid">Sound<small>${a.sound}</small></div><span>›</span></div>${sw('Always allow through','','allow',a.allow)}${sw('Verification codes','Raise from this app','codes',a.codes)}</div><div class="group"><h4>Focus exceptions</h4>${sw('Scroll blocker','','scroll',a.scroll)}${sw('Grayscale','','gray',a.gray)}${sw('Time limit and mindful launch','','limit',a.limit)}</div>`;
    } else b = `<input class="srch" placeholder="Search apps" id="q"><div class="group" id="apps">${S.apps.map((a,i)=>`<div class="row" data-app="${i}"><div class="ic">${a.name[0]}</div><div class="mid">${a.name}<small>${a.prio} priority${a.allow?' · always allowed':''}</small></div><span>›</span></div>`).join('')}</div>`;
  }
  if (S.settingsTab === 'focus') b = `<div class="group"><h4>Focus tools</h4><div class="row"><div class="mid">Scroll blocker<small>Per-app exceptions are in Apps</small></div><span>›</span></div><div class="row"><div class="mid">Grayscale</div><span>›</span></div><div class="row"><div class="mid">Time limit</div><span>›</span></div><div class="row"><div class="mid">Mindful launch</div><span>›</span></div></div>`;
  if (S.settingsTab === 'more' && S.flow) b = flowView();
  else if (S.settingsTab === 'more') b = accessGroup() + `<div class="group"><h4>Data</h4><div class="row"><div class="mid">Backup and restore</div><span>›</span></div></div><div class="group"><h4>App</h4><div class="row"><div class="mid">Theme</div><span>›</span></div><div class="row"><div class="mid">About</div><span>›</span></div></div>`;
  return `<div class="title" style="padding-bottom:0">Settings</div>${tabs}<div class="scroll">${b}</div>`;
}
function view(){
  if (S.tab==='inbox') return inbox();
  if (S.tab==='summary') return summary();
  if (S.tab==='launcher') return simple('Launcher',[['Calendar','Opens after a short pause'],['Maya Chat',''],['News','']],'App launcher. Not redesigned in this pass.');
  if (S.tab==='focus') return simple('Focus',[['Scroll blocker','Off'],['Grayscale','Off'],['Time limit','On'],['Mindful launch','On']],'Status and quick switches for the focus tools. Not redesigned in this pass.');
  return settings();
}
const mainScroll = () => document.querySelector('#phone > .scroll, #phone > .hdr ~ .scroll');
function render(){
  const tabs = [['inbox','✉','Inbox'],['summary','▤','Summary'],...(S.feat.launcher?[['launcher','▦','Launcher']]:[]),...(S.feat.focus?[['focus','◎','Focus']]:[]),['settings','⚙','Settings']];
  if (!tabs.some(t => t[0]===S.tab)) S.tab = 'settings';
  const key = [S.tab,S.inboxTab,S.settingsTab,S.app,S.variant].join('|');
  const keep = key === lastKey ? (mainScroll()?.scrollTop || 0) : 0; lastKey = key;
  const live = S.notes.find(n => n.id === S.shadeId);
  $('#phone').innerHTML = `<div class="shade ${S.shade?'':'hide'}"><div class="title" style="background:var(--tile)">Notification shade</div><div class="scroll">${live?`<div class="item" style="cursor:default"><div class="ic">F</div><div class="mid"><div class="top"><span class="nm">Farhan · ${esc(live.app)}</span><span class="tm">now</span></div><div class="tx">Verification code</div><div class="code">${live.code}</div><button class="btn pri" data-shadecopy>Copy code</button></div></div>`:''}<div class="note">Copy sets the clipboard, flagged sensitive. Android does not let an app collapse the shade, so it stays open, and the notification stays until you swipe it away. It is posted ahead of the schedule.</div><button class="btn" data-shadeclose style="align-self:flex-start">Close shade</button></div></div>${view()}<div class="nav">${tabs.map(t=>`<button class="${S.tab===t[0]?'on':''}" data-tab="${t[0]}"><i>${t[1]}</i>${t[2]}</button>`).join('')}</div><div class="toast" id="toast"></div>`;
  const sc = mainScroll(); if (sc) sc.scrollTop = keep;
}
$('#phone').addEventListener('click', e => {
  const g = a => e.target.closest(`[${a}]`), d = a => g(a).getAttribute(a);
  if (g('data-copy')) { render(); return toast('Copied. Marked sensitive.'); }
  if (g('data-shadecopy')) { S.shade = false; render(); return toast('Copied. Notification kept.'); }
  if (g('data-shadeclose')) { S.shade = false; return render(); }
  if (g('data-sel')) { const id = +d('data-sel'); S.selected.has(id) ? S.selected.delete(id) : S.selected.add(id); return render(); }
  if (g('data-clear')) {
    if (S.inboxTab === 'cleared') S.notes = S.notes.filter(n => !n.cleared);
    else { const ids = S.selected.size ? S.selected : new Set(S.notes.filter(n => !n.cleared).map(n => n.id)); S.notes.forEach(n => { if (ids.has(n.id)) n.cleared = true; }); S.selected.clear(); }
    return render();
  }
  if (g('data-open')) { const n = S.notes.find(n => n.id === +d('data-open')); const msg = n && !n.cleared ? (n.read = true, `Opened ${n.app}. Still in the list.`) : null; render(); if (msg) toast(msg); return; }
  if (g('data-itab')) { S.inboxTab = d('data-itab'); S.selected.clear(); return render(); }
  if (g('data-tab')) { S.tab = d('data-tab'); return render(); }
  if (g('data-stab')) { S.settingsTab = d('data-stab'); S.app = null; S.flow = null; return render(); }
  if (g('data-back')) { S.app = null; return render(); }
  if (g('data-app')) { S.app = +d('data-app'); return render(); }
  if (g('data-scope')) { S.codes.scope = S.codes.scope === 'All apps' ? 'Chosen apps' : 'All apps'; return render(); }
  if (g('data-cycle')) { const a = S.apps[S.app]; if (d('data-cycle') === 'prio') a.prio = {Low:'Medium',Medium:'High',High:'Critical',Critical:'Low'}[a.prio]; else a.sound = a.sound === 'Default' ? 'Silent' : 'Default'; return render(); }
  if (g('data-flow')) { S.flow = d('data-flow'); S.settingsTab = 'more'; S.tab = 'settings'; S.result = null; S.busy = false; return render(); }
  if (g('data-fback')) { S.flow = null; S.result = null; return render(); }
  if (g('data-retry')) { S.result = null; return render(); }
  if (g('data-route')) { S.route = d('data-route'); return render(); }
  if (g('data-toast')) { toast(d('data-toast')); return; }
  if (g('data-go')) {
    S.busy = true; render();
    setTimeout(() => {
      S.busy = false;
      if (S.outcome === 'nopair' && S.route === 'adb') S.result = {ok:false, msg:'Farhan could not pair. Check the code and port, and keep the pairing screen open in split screen.'};
      else if (S.outcome === 'noshiz' && S.route === 'shizuku') S.result = {ok:false, msg:'Shizuku is not running. Start it, then try again.'};
      else { S.result = {ok:true}; S.link = {route:S.route}; if (S.flow === 'sensitive') { S.access.sensitive = true; S.redaction = false; } else S.access.secure = true; }
      render();
    }, 1100);
    return;
  }
  if (g('data-tog') && d('data-tog').startsWith('a:')) {
    const k = d('data-tog').slice(2);
    const was = k === 'sensitive' ? S.access.sensitive : S.access.secure;
    if (S.outcome === 'lost' && S.link) { S.link = null; S.access = {sensitive:false, secure:false}; S.flow = k; S.settingsTab = 'more'; S.tab = 'settings'; S.busy = false; S.result = {ok:false, msg:'This phone no longer trusts Farhan. Pair again. Both accesses were switched off.'}; return render(); }
    if (S.outcome === 'noshiz' && S.link && S.link.route === 'shizuku') { toast('Shizuku is not running. Start it, then try again.'); return; }
    if (k === 'sensitive') { S.access.sensitive = !was; if (!was) S.redaction = false; } else S.access.secure = !was;
    if (!S.access.sensitive && !S.access.secure) { S.link = null; toast('Both off. Pairing forgotten.'); } else toast(was ? 'Revoked.' : 'Allowed.');
    return render();
  }
  if (g('data-tog')) {
    const k = d('data-tog');
    if (k in S.feat) S.feat[k] = !S.feat[k];
    else if (k === 'raise') S.codes.raise = !S.codes.raise;
    else if (S.app !== null && k in S.apps[S.app]) S.apps[S.app][k] = !S.apps[S.app][k];
    return render();
  }
});
