$('#hidden').onclick = () => { S.redaction = true; toast('Android hid a code from Farhan'); render(); };
document.querySelectorAll('#outcomes .chip').forEach(b => b.onclick = () => { S.outcome = b.dataset.o; document.querySelectorAll('#outcomes .chip').forEach(x => x.classList.toggle('on', x === b)); render(); });
$('#reset').onclick = () => { S = S0(); document.querySelectorAll('#outcomes .chip').forEach(b => b.classList.toggle('on', b.dataset.o === 'ok')); document.querySelectorAll('#variants .chip').forEach(b => b.classList.toggle('on', b.dataset.v === 'a')); render(); };
document.querySelectorAll('#variants .chip').forEach(b => b.onclick = () => { S.variant = b.dataset.v; S.tab = 'summary'; document.querySelectorAll('#variants .chip').forEach(x => x.classList.toggle('on', x === b)); render(); });
